package com.yeyamo_mobile.api.culture_service.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="culture_challenge_participants")public class CultureChallengeParticipant{@Id private UUID id;@Column(name="challenge_id",nullable=false)private UUID challengeId;@Column(name="user_id",nullable=false)private String userId;@Column(name="joined_at",nullable=false)private Instant joinedAt;@Column(name="completed_at")private Instant completedAt;protected CultureChallengeParticipant(){}public static CultureChallengeParticipant join(UUID challenge,String user){CultureChallengeParticipant p=new CultureChallengeParticipant();p.id=UUID.randomUUID();p.challengeId=challenge;p.userId=user;p.joinedAt=Instant.now();return p;}public void complete(){if(completedAt==null)completedAt=Instant.now();}public UUID getChallengeId(){return challengeId;}public String getUserId(){return userId;}public Instant getJoinedAt(){return joinedAt;}public Instant getCompletedAt(){return completedAt;}}
